from pathlib import Path
r=Path('/private/tmp/willyou-m12-p073-dialog-boundaries-native-001');p=r/'run.mjs';s=p.read_text().replace("import{createDialogFixture}from'./fixture.mjs'", "import{createBoundaryFixture}from'./fixture.mjs'").replace('const fixture=createDialogFixture()', 'const fixture=createBoundaryFixture()').replace("group:'M12-P070',case:'T062-full-I-and-explicit-modal-fixed6'", "group:'M12-P073A',case:'earlyinline-and-main-reference-modal'").replace('t062Cases:[],compatScenarios:[]','t062Cases:[],caseRows:[],compatScenarios:[]').replace("'t062Cases','compatScenarios'", "'t062Cases','caseRows','compatScenarios'")
