body=r'''const contract=JSON.parse(await readFile(root+'/contract.json')),plans=contract.cases.filter(x=>['early-inline-cold','main-reference-mousedown'].includes(x.id));assert.equal(plans.length,2);
 async function pageRead(label,pageId){const row=await ok(label,['browser','eval','--expression','window.bstate','--page',pageId]);return{step:row,value:JSON.parse(row.parsed.data.value)}}
 async function snapshotRef(label,pageId,name){const row=await ok(label,['browser','snapshot','--page',pageId]),data=row.parsed.data.result??row.parsed.data;assert(Array.isArray(data.refs),'Actualsnapshot refs absent');const found=data.refs.filter(x=>x.role==='button'&&x.name===name&&x.available);assert.equal(found.length,1,'Exactlyoneactual availablehostref required:'+name);return{step:row,ref:found[0].ref}}
 async function opening(row){return poll(async()=>{const state=await call({command:'dialog-state'});row.observations.push({at:Date.now(),pages:state.pages,pending:state.referenceCalls.filter(x=>!x.finishedAt&&!x.synchronousError).map(x=>({label:x.label,pageId:x.pageId,at:x.at,method:x.method}))});return state.dialogs.slice(row.beforeEventCount).find(x=>x.method==='Page.javascriptDialogOpening'&&x.params.message===row.message)},12000)}
 async function finishAnswer(row){row.closed=await poll(async()=>{const state=await call({command:'dialog-state'});return state.dialogs.slice(row.beforeEventCount).find(x=>x.pageId===row.pageId&&x.method==='Page.javascriptDialogClosed')},10000);row.siteResult=await poll(()=>fixture.results.find(x=>x.id===row.id),10000);row.afterDialog=await pageRead('afterdialog-'+row.id,row.pageId);row.nextRef=await snapshotRef('nextsnapshot-'+row.id,row.pageId,row.id+' next');row.nextClick=await cli('nextclick-'+row.id,['browser','click','--element',row.nextRef.ref,'--page',row.pageId]);row.afterNext=await pageRead('afternext-'+row.id,row.pageId)}
 for(const spec of plans){r.stage='P073A-'+spec.id;const before=await call({command:'dialog-state'}),row={id:'p073-'+spec.id,kind:spec.id,message:'P073 p073-'+spec.id,answerText:'accepted-'+spec.id+'-中文',beforeEventCount:before.dialogs.length,referenceCallStart:before.referenceCalls.length,observations:[],startedAtMs:Date.now()};r.caseRows.push(row);await persist();
  try{
   const path=spec.id==='early-inline-cold'?'/early-inline':'/main',url=cfg.origin+path+'?case='+encodeURIComponent(row.id);row.url=url;let createFinished=false;const createPromise=cli('create-'+row.id,['browser','tab','create','--url',url]).then(value=>{row.create=value;return value},error=>{row.createTransportError=String(error);return null}).finally(()=>createFinished=true);
   if(spec.id==='early-inline-cold'){row.opening=await opening(row);row.pageId=row.opening.pageId;row.coldState=await call({command:'dialog-state'});const actual=row.coldState.pages.find(x=>x.id===row.pageId);assert(actual);assert.equal(actual.helperActivePid,null);assert.equal(actual.helperDaemonPid,null);assert.equal(row.coldState.helperSpawnCount,0);row.frameBeforeAnswer=await call({command:'frame-state',pageId:row.pageId});row.answer=await cli('answer-'+row.id,['browser','dialog','accept','--text',row.answerText,'--page',row.pageId]);await createPromise;
   }else{await createPromise;const data=row.create?.parsed?.data?.result??row.create?.parsed?.data;assert.equal(row.create?.raw.code,0,'Actualplain pagecreate failed');row.pageId=data.pageId;assert.equal(typeof row.pageId,'string');await poll(()=>fixture.ready(row.id),10000);row.primaryRef=await snapshotRef('primarysnapshot-'+row.id,row.pageId,row.id+' primary');row.referenceBefore=await call({command:'reference-read',pageId:row.pageId,ref:row.primaryRef.ref});assert.equal(row.referenceBefore.hostClickComputed,false);row.frameBefore=await call({command:'frame-state',pageId:row.pageId});let clickDone=false,answerDone=false;const click=cli('primaryclick-'+row.id,['browser','click','--element',row.primaryRef.ref,'--page',row.pageId]).then(value=>row.click=value,error=>row.clickTransportError=String(error)).finally(()=>clickDone=true);row.opening=await opening(row);const answer=cli('answer-'+row.id,['browser','dialog','accept','--text',row.answerText,'--page',row.pageId]).then(value=>row.answer=value,error=>row.answerTransportError=String(error)).finally(()=>answerDone=true);
    while(!clickDone||!answerDone){await new Promise(ok=>setTimeout(ok,200));if(!clickDone||!answerDone){const state=await call({command:'dialog-state'});row.observations.push({at:Date.now(),pages:state.pages,pending:state.referenceCalls.filter(x=>!x.finishedAt&&!x.synchronousError).map(x=>({label:x.label,pageId:x.pageId,at:x.at,method:x.method}))});if(row.observations.length%5===0)await persist()}}await click;await answer;
   }
   if(row.answer?.raw.code===0&&row.create?.raw.code===0){await poll(()=>fixture.ready(row.id),10000);await finishAnswer(row)}else row.businessIncomplete='No normalanswer/create success; never forcedmodal';
  }catch(error){row.error=String(error.stack??error);row.errorStage=r.stage}
  row.afterState=await call({command:'dialog-state'});row.actualReferenceCalls=row.afterState.referenceCalls.slice(row.referenceCallStart);row.finishedAtMs=Date.now();await resources();await persist();
 }
 '''
s=s[:start]+body+s[end:];s=s.replace('r.siteResults=fixture.results;r.sitePointerEvents=fixture.events;', 'r.siteResults=fixture.results;r.sitePointerEvents=fixture.events;r.siteStates=fixture.states;');s=s.replace("r.knownPageIds=[r.page?.id,r.compatPageId].filter(Boolean)", "r.knownPageIds=[r.page?.id,...r.caseRows.map(x=>x.pageId)].filter(Boolean)")
